def-hyp[predicate](
    list-partial(
        Type.annotation(@P, Set(T@Set.ctxt.T)),
        Type.annotation(@Q, Set(S@Set.ctxt.S)),
        Type.annotation(@$\lt$, Rl(P,P)),
        Type.annotation(@$\ll$, Rl(Q,Q)),
        Set.order.partial(P, $\lt$),
        Set.order.partial(Q, $\ll$),
        Type.annotation(@f, Type.to(P,Q))
    ),
    Set.order.isomorphism(f, P, Q),
    Logic.forall-typed(
        @x,
        P,
        Logic.forall-typed(
            @y,
            P,
            Logic.iff(Rl.apply($\lt$, x, y), Rl.apply($\ll$, Type.apply(f, x), Type.apply(f, y)))
        )
    )
)
